// regra — contrato do /health: api/worker.py:84-103; versão por componentes: api/worker.py:39-50
// Normaliza as duas saídas do HTTP (sucesso e erro de rede) num item só, para
// que "worker inalcançável" vire linha em `saude` e e-mail — nunca silêncio.
const esperadoTess = String($env.FOPA_TESSERACT_ESPERADO || '5.4.0');
const esperadoSha = String($env.FOPA_TESSDATA_SHA256 || '');
const r = $input.first().json || {};
const corpo = (r.body && typeof r.body === 'object') ? r.body : {};
const status = r.statusCode ?? null;
let falhaRede = null;
if (r.error) falhaRede = String(r.error.message || r.error.description || JSON.stringify(r.error));

// '5.4.0' casa com '5.4.0.20240606' e NÃO com '5.4.1' nem '5.4.01' (ADR-008).
const versaoBate = (obtida, esperada) => {
  const o = String(obtida || '').split('.');
  const e = esperada.split('.');
  return e.every((p, i) => o[i] === p);
};

const motivos = [];
if (falhaRede) {
  motivos.push('worker inalcançável: ' + falhaRede);
} else {
  if (status !== 200) motivos.push(`/health respondeu HTTP ${status}` + (corpo.erro ? ` (${corpo.erro})` : ''));
  if (!versaoBate(corpo.tesseract, esperadoTess)) motivos.push(`tesseract ${corpo.tesseract} ≠ ${esperadoTess}`);
  if (esperadoSha && corpo.tessdata_sha256 !== esperadoSha) motivos.push('tessdata_sha256 difere do pinado no build');
  if (corpo.anthropic_key_presente === true) motivos.push('worker recebeu ANTHROPIC_API_KEY (só o n8n pode ter)');
}

// regra — link da execução robusto: a base (N8N_EDITOR_BASE_URL, senão WEBHOOK_URL) pode vir com ou sem
// barra no fim; sem base nenhuma, o e-mail diz o id sem link (antes: $env.WEBHOOK_URL + 'workflow/...'
// supunha a barra e gerava 'http://hostworkflow/...' quando ela faltava).
const baseN8n = String($env.N8N_EDITOR_BASE_URL || $env.WEBHOOK_URL || '').trim().replace(/\/+$/, '');
const linkExecucao = baseN8n ? `${baseN8n}/workflow/${$workflow.id}/executions/${$execution.id}` : '';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const execucao = linkExecucao
  ? `<a href="${esc(linkExecucao)}">${esc($execution.id)}</a>` : esc($execution.id);
const corpoEmail = '<p>O W00 encontrou o worker fora do contrato do /health.</p><ul>'
  + motivos.map((m) => '<li>' + esc(m) + '</li>').join('') + '</ul><p>Execução ' + execucao + '</p>';

return [{ json: {
  worker_ok: !falhaRede && status === 200 && corpo.ok === true,
  tesseract: corpo.tesseract ?? null,
  tesseract_ok: versaoBate(corpo.tesseract, esperadoTess),
  tessdata_sha256: corpo.tessdata_sha256 ?? null,
  git_sha: corpo.git_sha ?? null,
  motivos,
  link_execucao: linkExecucao,
  corpo_email: corpoEmail,
  detalhes: { http_status: status, corpo, motivos, n8n_execution_id: String($execution.id),
              link_execucao: linkExecucao,
              esperado: { tesseract: esperadoTess, tessdata_sha256: esperadoSha } },
} }];
